create table if not exists public.banners (accent text, active boolean default true, btn_text text, category text, created_at timestamptz default now(), description text, id bigint generated by default as identity primary key, image text, link text, sort_order bigint, subtitle text, title text, updated_at timestamptz default now());
create table if not exists public.berita (active boolean default true, author text, category text, content text, created_at timestamptz default now(), event_date text, featured boolean, id bigint generated by default as identity primary key, image text, location text, photo_source text, published_at timestamptz, slug text, source_name text, source_url text, status text, submitter_email text, submitter_name text, summary text, title text, updated_at timestamptz default now());
create table if not exists public.digital_services (active boolean default true, category text, created_at timestamptz default now(), description text, featured boolean, id bigint generated by default as identity primary key, image text, price numeric, title text, updated_at timestamptz default now(), whatsapp text);
create table if not exists public.event_tickets (active boolean default true, created_at timestamptz default now(), description text, event_id bigint, id bigint generated by default as identity primary key, name text, price numeric, quota numeric, sale_end text, sale_start text, sold numeric, sort_order bigint);
create table if not exists public.events (active boolean default true, allow_voucher boolean, banner_image text, category text, created_at timestamptz default now(), crew_active boolean, date text, date_end text, description text, featured boolean, guest_stars jsonb, id bigint generated by default as identity primary key, image text, location text, maps_url text, menu_items jsonb, name text, organizer text, organizer_ig text, payment_info jsonb, price numeric, prohibited_items jsonb, rundown jsonb, service_fee_percent numeric, slug text, time_end text, time_start text, title text, transportation_info jsonb, updated_at timestamptz default now(), visitors numeric);
create table if not exists public.influencers (active boolean default true, bio text, color text, color2 text, created_at timestamptz default now(), handle text, id bigint generated by default as identity primary key, instagram text, location text, name text, niches text[], photos text[], rate text, rating numeric, sort_order bigint, tiktok text, updated_at timestamptz default now(), verified boolean);
create table if not exists public.kamus_sunda (active boolean default true, category text, created_at timestamptz default now(), example text, id bigint generated by default as identity primary key, indonesia text, latin text, level text, sunda text, updated_at timestamptz default now());
create table if not exists public.kuliner (active boolean default true, category text, created_at timestamptz default now(), description text, facilities text, featured boolean, google_maps_url text, hours text, id bigint generated by default as identity primary key, image text, instagram text, location text, maps_embed_url text, name text, phone text, photos text, price_range text, rating numeric, reservasi_enabled boolean, slug text, updated_at timestamptz default now(), website text);
create table if not exists public.partners (active boolean default true, color text, created_at timestamptz default now(), id bigint generated by default as identity primary key, name text, sort_order bigint, updated_at timestamptz default now());
create table if not exists public.penginapan (active boolean default true, amenities text[], booking_enabled boolean, category text, created_at timestamptz default now(), description text, featured boolean, id bigint generated by default as identity primary key, image text, instagram text, location text, name text, price_per_night numeric, rating numeric, slug text, updated_at timestamptz default now());
create table if not exists public.perlombaan (active boolean default true, category text, created_at timestamptz default now(), date text, description text, featured boolean, fee numeric, id bigint generated by default as identity primary key, image text, location text, max_peserta numeric, name text, organizer text, prize numeric);
create table if not exists public.price_list (active boolean default true, category text, created_at timestamptz default now(), description text, id bigint generated by default as identity primary key, item text, price numeric, sort_order bigint, updated_at timestamptz default now());
create table if not exists public.promo_banners (active boolean default true, created_at timestamptz default now(), id bigint generated by default as identity primary key, image text, link text, sort_order bigint, updated_at timestamptz default now());
create table if not exists public.site_settings (key text primary key, updated_at timestamptz default now(), value text);
create table if not exists public.talents (active boolean default true, bio text, category text, created_at timestamptz default now(), featured boolean, id bigint generated by default as identity primary key, instagram text, name text, photo text, role text, sort_order bigint, tagline text, tags text[], updated_at timestamptz default now(), verified boolean, wa text);
create table if not exists public.transportasi (active boolean default true, asal text, created_at timestamptz default now(), description text, frekuensi text, id bigint generated by default as identity primary key, jam text, kode text, name text, tarif numeric, tujuan text, type text, updated_at timestamptz default now(), via text);
create table if not exists public.vouchers (active boolean default true, applicable_type text, code text, created_at timestamptz default now(), description text, discount_type text, discount_value numeric, expiry_date text, id bigint generated by default as identity primary key, kuliner_id bigint, min_purchase numeric, mitra_id bigint, required_points numeric, title text, type text, updated_at timestamptz default now());
create table if not exists public.wisata (active boolean default true, category text, created_at timestamptz default now(), description text, entry_fee numeric, facilities text, google_maps_url text, id bigint generated by default as identity primary key, image text, instagram text, location text, maps_embed_url text, name text, opening_hours text, partner boolean, phone text, photos text, rating numeric, slug text, updated_at timestamptz default now(), website text);
do $$
declare t text;
begin
  foreach t in array array['banners','berita','digital_services','event_tickets','events','influencers','kamus_sunda','kuliner','partners','penginapan','perlombaan','price_list','promo_banners','site_settings','talents','transportasi','vouchers','wisata'] loop
    execute format('grant select on public.%I to anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists "Public read %s" on public.%I', t, t);
    execute format('create policy "Public read %s" on public.%I for select to anon, authenticated using (true)', t, t);
  end loop;
end $$;